/// <summary>
/// Exclude rebate charge codes from the PO line charge code lookup
/// </summary>
/// <returns>The <c>Query</c> object including ranges.</returns>
protected Query buildMarkupTableQuery()
{
    Query query = next buildMarkupTableQuery();

    if (this.MarkupTrans.ModuleType == MarkupModuleType::Vend
    &&  this.MarkupTrans.ModuleCategory == HeadingLine::Line)
    {
        query.dataSourceTable(tableNum(MarkupTable)).addRange(fieldNum(MarkupTable, METIsRebateCode)).value(queryValue(NoYes::No));
    }

    return query;
}
